import { pgEnum } from "drizzle-orm/pg-core";

export const accountTypeEnum = pgEnum("account_type", [
  "asset",
  "cash",
  "wallet",
  "credit_card",
  "liability",
  "investment",
]);

export const transactionTypeEnum = pgEnum("transaction_type", [
  "income",
  "expense",
  "transfer",
  "adjustment",
  "opening_balance",
]);

/**
 * Lifecycle of a transaction:
 * - pending:  draft generated by a recurring template, awaiting review
 * - imported: created from an import, awaiting review
 * - reviewed: human-confirmed but not yet considered final
 * - posted:   final ledger entry (manual entries start here)
 * - rejected: excluded from the ledger, kept for audit/provenance
 */
export const transactionStatusEnum = pgEnum("transaction_status", [
  "pending",
  "imported",
  "reviewed",
  "posted",
  "rejected",
]);

export const importFileStatusEnum = pgEnum("import_file_status", [
  "uploaded",
  "mapped",
  "previewed",
  "committed",
  "failed",
]);

export const importRowStatusEnum = pgEnum("import_row_status", [
  "pending",
  "approved",
  "rejected",
  "duplicate",
  "error",
]);

export const recurrenceIntervalEnum = pgEnum("recurrence_interval", [
  "weekly",
  "monthly",
  "quarterly",
  "yearly",
]);

